// Build the LocalAI request body as a real JS object.
// This is the fix your team already found in the original workflow:
// n8n's {{ }} expression syntax does not support JSON.stringify()
// the way plain JavaScript does, so the request body must be built
// here in a Code node, not templated as a string.

const alert = items[0].json;

const systemPrompt = "You are a SOC analyst. Classify this Wazuh alert as " +
  "true_positive or false_positive. Respond ONLY with valid JSON in this " +
  "exact format: {'verdict': 'true_positive or false_positive', " +
  "'confidence': a number 0 to 100, 'reason': 'short explanation', " +
  "'source_ip': 'extracted IP if present'}";

const alertText = JSON.stringify(alert);

const payload = {
  model: "Qwen2.5-7B-Instruct-Q4_K_M.gguf",
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user", content: alertText }
  ]
};

return [{ json: { payload, original_alert: alert } }];

// Parse LocalAI's response into a clean verdict object.
// Handles the model sometimes prefixing the JSON with stray text,
// and single-quoted JSON-like output (both seen in production).

const response = items[0].json;
const rawContent = response.choices[0].message.content;

const jsonStart = rawContent.indexOf('{');
if (jsonStart === -1) {
  throw new Error('No JSON object found in LocalAI output: ' + rawContent);
}

const verdictText = rawContent.slice(jsonStart).replace(/'/g, '"');
const verdict = JSON.parse(verdictText);

// Carry the original alert through for the GLPI ticket step.
const originalAlert = $('Build LocalAI Request').item.json.original_alert;

return [{
  json: {
    verdict: verdict.verdict,
    confidence: verdict.confidence,
    reason: verdict.reason,
    source_ip: verdict.source_ip,
    original_alert: originalAlert
  }
}];

// Build the GLPI ticket payload.
// Critical fix from the original build: GLPI expects `input` to be a
// JSON OBJECT, not an array -- sending an array causes ERROR_BAD_ARRAY.

const verdictData = $('Is True Positive?').item.json;
const sessionToken = items[0].json.session_token;

const alert = verdictData.original_alert || {};
const ruleId = (alert.rule && alert.rule.id) || 'unknown';
const ruleDesc = (alert.rule && alert.rule.description) || 'Wazuh alert';

const ticketBody =
  'Automated ticket created from Wazuh alert.\n\n' +
  'Rule ID: ' + ruleId + '\n' +
  'Description: ' + ruleDesc + '\n' +
  'Source IP: ' + verdictData.source_ip + '\n' +
  'LocalAI verdict: ' + verdictData.verdict + ' (' + verdictData.confidence + '% confidence)\n' +
  'Reason: ' + verdictData.reason;

const payload = {
  input: {
    name: 'Security Alert - Rule ' + ruleId + ' - ' + verdictData.source_ip,
    content: ticketBody,
    urgency: verdictData.confidence >= 80 ? 5 : 3,
    type: 1
  }
};

return [{ json: { payload, session_token: sessionToken } }];
